CREATE TABLE "public"."project_roles" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "edited_at"  timestamp with time zone NOT NULL DEFAULT now(),
  "project"    bigint                   NOT NULL,
  "user"       bigint                   NOT NULL,
  CONSTRAINT "project_roles_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."project_roles"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."projects" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "Title"      text,
  "edited_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "projects_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."projects"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."public_users" (
  "id"         bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "auth_id"    uuid,
  "address"    text,
  CONSTRAINT "public_users_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."public_users"
  ENABLE ROW LEVEL SECURITY;

CREATE TYPE "public"."project_permissions" AS ENUM (
  'owner',
  'editor',
  'viewer'
);

ALTER TABLE "public"."project_roles"
  ADD COLUMN "role" public.project_permissions NOT NULL DEFAULT 'viewer'::public.project_permissions;

ALTER TABLE "public"."project_roles"
  ADD CONSTRAINT "project_roles_project_fkey" FOREIGN KEY (project) REFERENCES public.projects(id) ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."project_roles"
  ADD CONSTRAINT "project_roles_user_fkey" FOREIGN KEY ("user") REFERENCES public.public_users(id);

